import functools, time

# ── 1. repeat(n): call function n times ─────────────────────
def repeat(n):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            results = [func(*args, **kwargs) for _ in range(n)]
            return results[-1]   # return last result
        return wrapper
    return decorator

@repeat(3)
def hello(name):
    print(f"Hello, {name}!")

hello("Bob")
# Hello, Bob!
# Hello, Bob!
# Hello, Bob!

# ── 2. Type validation decorator ────────────────────────────
def validate_types(**expected):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(**kwargs):
            for key, typ in expected.items():
                if key in kwargs and not isinstance(kwargs[key], typ):
                    raise TypeError(
                        f"Arg '{key}' expected {typ.__name__}, "
                        f"got {type(kwargs[key]).__name__}")
            return func(**kwargs)
        return wrapper
    return decorator

@validate_types(name=str, age=int)
def register(name, age):
    print(f"Registered: {name}, {age}")

register(name="Alice", age=25)    # OK
try:
    register(name="Bob", age="25")  # TypeError!
except TypeError as e:
    print(e)   # Arg 'age' expected int, got str

# ── 3. rate_limit(calls_per_sec) ────────────────────────────
def rate_limit(calls_per_sec):
    interval = 1.0 / calls_per_sec
    def decorator(func):
        last_called = [0.0]        # mutable cell trick
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            elapsed = time.time() - last_called[0]
            if elapsed < interval:
                time.sleep(interval - elapsed)
            last_called[0] = time.time()
            return func(*args, **kwargs)
        return wrapper
    return decorator

@rate_limit(calls_per_sec=2)   # max 2 calls per second
def api_call(endpoint):
    return f"response from {endpoint}"

# ── 4. Combining @wraps with argument inspection ─────────────
import inspect

def log_calls(level="INFO"):
    def decorator(func):
        sig = inspect.signature(func)
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()
            print(f"[{level}] {func.__name__}({dict(bound.arguments)})")
            result = func(*args, **kwargs)
            print(f"[{level}] returned: {result!r}")
            return result
        return wrapper
    return decorator

@log_calls(level="DEBUG")
def divide(a, b=1):
    return a / b

divide(10, b=2)
# [DEBUG] divide({'a': 10, 'b': 2})
# [DEBUG] returned: 5.0

