# Q2: Stacking order
def p(c):
    def dec(f):
        def w(*a,**k):
            print(c, end=" ")
            return f(*a,**k)
        return w
    return dec

@p("1") @p("2") @p("3")
def fn(): print("X")
fn()   # 1 2 3 X  (d1 runs first, prints 1; d2 prints 2; d3 prints 3)

# Q3: wraps vs no wraps
def bad(f):
    def wrapper(): return f()
    return wrapper

def good(f):
    @functools.wraps(f)
    def wrapper(): return f()
    return wrapper

@bad
def foo(): """foo docstring"""; pass
@good
def bar(): """bar docstring"""; pass

print(foo.__name__)   # wrapper  (LOST original name)
print(bar.__name__)   # bar      (preserved by @wraps)
print(foo.__doc__)    # None
print(bar.__doc__)    # bar docstring

# Q4: decorator = factory call at definition time
import functools

def count_calls(func):
    @functools.wraps(func)
    def wrapper(*a, **k):
        wrapper.calls += 1
        return func(*a, **k)
    wrapper.calls = 0    # attach counter to wrapper function!
    return wrapper

@count_calls
def add(x, y): return x + y

add(1,2); add(3,4); add(5,6)
print(add.calls)   # 3

